88	     7	
89	     8	/** Mock Q&A patterns keyed to document content keywords. */
90	     9	const MOCK_PATTERNS: Array<{
91	    10	  keywords: string[];
92	    11	  answer: string;
93	    12	  excerpt: string;
94	    13	}> = [
95	    14	  {
96	    15	    keywords: ['design', 'architecture', 'pattern'],
97	    16	    answer: 'The system uses a layered architecture with clear boundaries between the main process, preload scripts, and renderer. Each layer communicates through typed IPC channels, and the services layer handles business logic independently of the UI.',
98	    17	    excerpt: 'The system uses a layered architecture with clear boundaries',
99	    18	  },
100	    19	  {
101	    20	    keywords: ['import', 'document', 'file'],
102	    21	    answer: 'Documents are imported by copying the source file to the local data directory. The system extracts text content and creates metadata including title, filename, size, and import timestamp. After import, documents can be indexed for search.',
103	    22	    excerpt: 'Documents are imported by copying the source file',
104	    23	  },
105	    24	  {
106	    25	    keywords: ['index', 'chunk', 'search'],
107	    26	    answer: 'The indexing pipeline splits documents into chunks of approximately 500 characters at paragraph boundaries. Each chunk includes metadata like character count and word count. The index enables grounded Q&A with citations pointing to specific document sections.',
108	    27	    excerpt: 'The indexing pipeline splits documents into chunks',
109	    28	  },
110	    29	  {
111	    30	    keywords: ['retrieval', 'search', 'query'],
112	    31	    answer: 'Retrieval works by matching query keywords against indexed chunks. The system ranks chunks by keyword overlap and returns the most relevant excerpts as citations alongside the generated answer.',
113	    32	    excerpt: 'Retrieval works by matching query keywords against indexed chunks',
114	    33	  },
115	    34	  {
116	    35	    keywords: ['meeting', 'notes', 'summary'],
117	    36	    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
118	    37	    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
119	    38	  },
120	    39	];
121	    40	
122	    41	export class QaService {
123	    42	  private persistence: PersistenceService;
124	    43	  private indexingService: IndexingService;
125	    44	  private log = logger.forService('QaService');
126	    45	
127	    46	  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
128	    47	    this.persistence = persistence;
129	    48	    this.indexingService = indexingService ?? new IndexingService(persistence);
130	    49	    this.log.info('QaService initialized');
131	    50	  }
132	    51	
133	    52	  /** Ask a question and get a grounded answer with citations. */
134	    53	  async ask(question: string): Promise<QAResponse> {
135	    54	    this.log.info('Processing question', { question });
136	    55	
137	    56	    // Simulate processing delay
138	    57	    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));
139	    58	
140	    59	    const chunks = this.indexingService.getAllChunks();
141	    60	    const citations: Citation[] = [];
142	    61	
143	    62	    this.log.info('Retrieving from chunks', { totalChunks: chunks.length });
144	    63	
145	    64	    if (chunks.length > 0) {
146	    65	      // Find relevant chunks using keyword matching
147	    66	      const questionWords = question.toLowerCase().split(/\s+/).filter(w => w.length > 2);
148	    67	      const scored = chunks.map(chunk => {
149	    68	        const contentLower = chunk.content.toLowerCase();
150	    69	        const score = questionWords.reduce(
151	    70	          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
152	    71	          0
153	    72	        );
154	    73	        return { chunk, score };
155	    74	      });
156	    75	
157	    76	      // Take top 2 relevant chunks as citations
158	    77	      const relevant = scored
159	    78	        .filter(s => s.score > 0)
160	    79	        .sort((a, b) => b.score - a.score)
161	    80	        .slice(0, 2);
162	    81	
163	    82	      this.log.info('Keyword matching results', {
164	    83	        questionWords: questionWords.length,
165	    84	        relevantChunks: relevant.length,
166	    85	      });
167	    86	
168	    87	      // Get document metadata for citations
169	    88	      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
170	    89	
171	    90	      for (const { chunk } of relevant) {
172	    91	        const doc = docs.find(d => d.id === chunk.documentId);
173	    92	        citations.push({
174	    93	          documentId: chunk.documentId,
175	    94	          documentTitle: doc?.title ?? 'Unknown Document',
176	    95	          chunkIndex: chunk.index,
177	    96	          excerpt: chunk.content.substring(0, 200),
178	    97	        });
179	    98	      }
180	    99	    }
181	   100	
182	   101	    // Generate answer from mock patterns or use fallback
183	   102	    const answer = this.generateAnswer(question, citations);
184	   103	
185	   104	    const response: QAResponse = {
186	   105	      answer,
187	   106	      citations,
188	   107	      confidence: citations.length > 0 ? 0.85 : 0.3,
189	   108	      timestamp: new Date().toISOString(),
190	   109	    };
191	   110	
192	   111	    this.log.info('Q&A response generated', {
193	   112	      confidence: response.confidence,
194	   113	      citationCount: citations.length,
195	   114	      answerLength: answer.length,
196	   115	    });
197	   116	
198	   117	    // Save to history
199	   118	    this.saveToHistory(question, response);
200	   119	
201	   120	    return response;
202	   121	  }
203	   122	
204	   123	  /** Get the Q&A history. */
205	   124	  getHistory(): QAHistory[] {
206	   125	    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
207	   126	  }
208	   127	
209	   128	  /** Clear the Q&A history. */
210	   129	  clearHistory(): void {
211	   130	    this.persistence.writeJson(QA_HISTORY_FILE, []);
212	   131	    this.log.info('Q&A history cleared');
213	   132	  }
214	   133	
215	   134	  private generateAnswer(question: string, citations: Citation[]): string {
216	   135	    // Match against mock patterns
217	   136	    const questionLower = question.toLowerCase();
218	   137	    for (const pattern of MOCK_PATTERNS) {
219	   138	      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
220	   139	        if (citations.length > 0) {
221	   140	          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
222	   141	        }
223	   142	        return pattern.answer;
224	   143	      }
225	   144	    }
226	   145	
227	   146	    // Fallback answer
228	   147	    if (citations.length > 0) {
229	   148	      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
230	   149	    }
231	   150	
232	   151	    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
233	   152	  }
234	   153	
235	   154	  private saveToHistory(question: string, response: QAResponse): void {
236	   155	    const history = this.getHistory();
237	   156	    history.push({ question, response });
238	   157	    this.persistence.writeJson(QA_HISTORY_FILE, history);
239	   158	    this.log.info('Question saved to history', { historyLength: history.length });
240	   159	  }
241	   160	}
