761	     1	#!/usr/bin/env bash
762	     2	#
763	     3	# check-architecture.sh - Verify layer boundary constraints
764	     4	#
765	     5	# Checks that:
766	     6	# 1. No Node.js core modules (fs, path, os, child_process) in renderer code
767	     7	# 2. No Electron IPC imports in service code
768	     8	# 3. No React imports in services or main process code
769	     9	#
770	    10	# Exit code 0 = all checks pass
771	    11	# Exit code 1 = violations found
772	    12	
773	    13	set -euo pipefail
774	    14	
775	    15	VIOLATIONS=0
776	    16	
777	    17	echo "=== Architecture Boundary Checks ==="
778	    18	echo ""
779	    19	
780	    20	# Check 1: No fs/path imports in renderer
781	    21	echo "Checking renderer for Node.js core module imports..."
782	    22	RENDERER_FILES=$(find src/renderer -name '*.ts' -o -name '*.tsx' 2>/dev/null || true)
783	    23	if [ -n "$RENDERER_FILES" ]; then
784	    24	  while IFS= read -r file; do
785	    25	    if grep -qE "import.*\b(fs|path|os|child_process)\b" "$file" 2>/dev/null; then
786	    26	      echo "  VIOLATION: $file imports Node.js core module"
787	    27	      VIOLATIONS=$((VIOLATIONS + 1))
788	    28	    fi
789	    29	  done <<< "$RENDERER_FILES"
790	    30	fi
791	    31	if [ "$VIOLATIONS" -eq 0 ]; then
792	    32	  echo "  PASS: No Node.js core imports in renderer"
793	    33	fi
794	    34	echo ""
795	    35	
796	    36	# Check 2: No Electron IPC in services
797	    37	echo "Checking services for Electron IPC imports..."
798	    38	SERVICE_FILES=$(find src/services -name '*.ts' 2>/dev/null || true)
799	    39	SVIO=0
800	    40	if [ -n "$SERVICE_FILES" ]; then
801	    41	  while IFS= read -r file; do
802	    42	    if grep -qE "import.*from\s+['\"]electron['\"]" "$file" 2>/dev/null; then
803	    43	      echo "  VIOLATION: $file imports from electron"
804	    44	      VIOLATIONS=$((VIOLATIONS + 1))
805	    45	      SVIO=$((SVIO + 1))
806	    46	    fi
807	    47	    if grep -qE "\bipcMain\b|\bipcRenderer\b|\bBrowserWindow\b" "$file" 2>/dev/null; then
808	    48	      echo "  VIOLATION: $file uses Electron IPC"
809	    49	      VIOLATIONS=$((VIOLATIONS + 1))
810	    50	      SVIO=$((SVIO + 1))
811	    51	    fi
812	    52	  done <<< "$SERVICE_FILES"
813	    53	fi
814	    54	if [ "$SVIO" -eq 0 ]; then
815	    55	  echo "  PASS: No Electron IPC in services"
816	    56	fi
817	    57	echo ""
818	    58	
819	    59	# Check 3: No React imports in services or main
820	    60	echo "Checking services and main for React imports..."
821	    61	BACKEND_FILES=$(find src/services src/main -name '*.ts' 2>/dev/null || true)
822	    62	RVIO=0
823	    63	if [ -n "$BACKEND_FILES" ]; then
824	    64	  while IFS= read -r file; do
825	    65	    if grep -qE "import.*from\s+['\"]react['\"]" "$file" 2>/dev/null; then
826	    66	      echo "  VIOLATION: $file imports React"
827	    67	      VIOLATIONS=$((VIOLATIONS + 1))
828	    68	      RVIO=$((RVIO + 1))
829	    69	    fi
830	    70	  done <<< "$BACKEND_FILES"
831	    71	fi
832	    72	if [ "$RVIO" -eq 0 ]; then
833	    73	  echo "  PASS: No React imports in services/main"
834	    74	fi
835	    75	echo ""
836	    76	
837	    77	# Summary
838	    78	echo "=== Summary ==="
839	    79	if [ "$VIOLATIONS" -gt 0 ]; then
840	    80	  echo "FAIL: $VIOLATIONS violation(s) found"
841	    81	  exit 1
842	    82	else
843	    83	  echo "PASS: All architecture boundary checks passed"
844	    84	  exit 0
845	    85	fi
