     3	import { IndexingService } from './indexing-service';
     4	import { logger } from './logger';
     5	
     6	const QA_HISTORY_FILE = 'qa-history.json';
     7	
     8	/** Mock Q&A patterns keyed to document content keywords. */
     9	const MOCK_PATTERNS: Array<{
    10	  keywords: string[];
    11	  answer: string;
    12	  excerpt: string;
    13	}> = [
    14	  {
    15	    keywords: ['design', 'architecture', 'pattern'],
    16	    answer: 'The system uses a layered architecture with clear boundaries between the main process, preload scripts, and renderer. Each layer communicates through typed IPC channels, and the services layer handles business logic independently of the UI.',
    17	    excerpt: 'The system uses a layered architecture with clear boundaries',
    18	  },
    19	  {
    20	    keywords: ['import', 'document', 'file'],
    21	    answer: 'Documents are imported by copying the source file to the local data directory. The system extracts text content and creates metadata including title, filename, size, and import timestamp. After import, documents can be indexed for search.',
    22	    excerpt: 'Documents are imported by copying the source file',
    23	  },
    24	  {
    25	    keywords: ['index', 'chunk', 'search'],
    26	    answer: 'The indexing pipeline splits documents into chunks of approximately 500 characters at paragraph boundaries. Each chunk includes metadata like character count and word count. The index enables grounded Q&A with citations pointing to specific document sections.',
    27	    excerpt: 'The indexing pipeline splits documents into chunks',
    28	  },
    29	  {
    30	    keywords: ['retrieval', 'search', 'query'],
    31	    answer: 'Retrieval works by matching query keywords against indexed chunks. The system ranks chunks by keyword overlap and returns the most relevant excerpts as citations alongside the generated answer.',
    32	    excerpt: 'Retrieval works by matching query keywords against indexed chunks',
    33	  },
    34	  {
    35	    keywords: ['meeting', 'notes', 'summary'],
    36	    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
    37	    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
    38	  },
    39	];
    40	
    41	export class QaService {
    42	  private persistence: PersistenceService;
    43	  private indexingService: IndexingService;
    44	  private log = logger.forService('QaService');
    45	
    46	  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
    47	    this.persistence = persistence;
    48	    this.indexingService = indexingService ?? new IndexingService(persistence);
    49	    this.log.info('QaService initialized');
    50	  }
    51	
    52	  /** Ask a question and get a grounded answer with citations. */
    53	  async ask(question: string): Promise<QAResponse> {
    54	    this.log.info('Processing question', { question });
    55	
    56	    // Simulate processing delay
    57	    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));
    58	
    59	    const chunks = this.indexingService.getAllChunks();
    60	    const citations: Citation[] = [];
    61	
    62	    this.log.info('Retrieving from chunks', { totalChunks: chunks.length });
    63	
    64	    if (chunks.length > 0) {
    65	      // Find relevant chunks using keyword matching
    66	      const questionWords = question.toLowerCase().split(/\s+/).filter(w => w.length > 2);
    67	      const scored = chunks.map(chunk => {
    68	        const contentLower = chunk.content.toLowerCase();
    69	        const score = questionWords.reduce(
    70	          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
    71	          0
    72	        );
    73	        return { chunk, score };
    74	      });
    75	
    76	      // Take top 2 relevant chunks as citations
    77	      const relevant = scored
    78	        .filter(s => s.score > 0)
    79	        .sort((a, b) => b.score - a.score)
    80	        .slice(0, 2);
    81	
    82	      this.log.info('Keyword matching results', {
    83	        questionWords: questionWords.length,
    84	        relevantChunks: relevant.length,
    85	      });
    86	
    87	      // Get document metadata for citations
    88	      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
    89	
    90	      for (const { chunk } of relevant) {
    91	        const doc = docs.find(d => d.id === chunk.documentId);
    92	        citations.push({
    93	          documentId: chunk.documentId,
    94	          documentTitle: doc?.title ?? 'Unknown Document',
    95	          chunkIndex: chunk.index,
    96	          excerpt: chunk.content.substring(0, 200),
    97	        });
    98	      }
    99	    }
   100	
   101	    // Generate answer from mock patterns or use fallback
   102	    const answer = this.generateAnswer(question, citations);
   103	
   104	    const response: QAResponse = {
   105	      answer,
   106	      citations,
   107	      confidence: citations.length > 0 ? 0.85 : 0.3,
   108	      timestamp: new Date().toISOString(),
   109	    };
   110	
   111	    this.log.info('Q&A response generated', {
   112	      confidence: response.confidence,
   113	      citationCount: citations.length,
   114	      answerLength: answer.length,
   115	    });
   116	
   117	    // Save to history
   118	    this.saveToHistory(question, response);
   119	
   120	    return response;
   121	  }
   122	
   123	  /** Get the Q&A history. */
   124	  getHistory(): QAHistory[] {
   125	    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
   126	  }
   127	
   128	  /** Clear the Q&A history. */
   129	  clearHistory(): void {
   130	    this.persistence.writeJson(QA_HISTORY_FILE, []);
   131	    this.log.info('Q&A history cleared');
   132	  }
   133	
   134	  private generateAnswer(question: string, citations: Citation[]): string {
   135	    // Match against mock patterns
   136	    const questionLower = question.toLowerCase();
   137	    for (const pattern of MOCK_PATTERNS) {
   138	      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
   139	        if (citations.length > 0) {
   140	          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
   141	        }
   142	        return pattern.answer;
   143	      }
   144	    }
   145	
   146	    // Fallback answer
   147	    if (citations.length > 0) {
   148	      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
   149	    }
   150	
   151	    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
   152	  }
   153	
   154	  private saveToHistory(question: string, response: QAResponse): void {
   155	    const history = this.getHistory();
   156	    history.push({ question, response });
   157	    this.persistence.writeJson(QA_HISTORY_FILE, history);
   158	    this.log.info('Question saved to history', { historyLength: history.length });
   159	  }
   160	}
