import { useEffect, useMemo, useRef, useState } from 'react';
import { ConversationExchange } from '../../shared/types';
import { ExchangeItem, metaText, smallButton, userBubble } from './ExchangeItem';

export interface PendingQuestion {
  question: string;
  followUpOf: string | null;
}

export interface FailedQuestion extends PendingQuestion {
  message: string;
}

/** A request to scroll to and highlight an exchange; `seq` lets the same exchange be selected twice. */
export interface ExchangeSelection {
  id: string;
  seq: number;
}

interface Props {
  conversation: ConversationExchange[];
  historyError: string | null;
  pending: PendingQuestion | null;
  failed: FailedQuestion | null;
  selection: ExchangeSelection | null;
  isDocumentAvailable: (documentId: string) => boolean;
  onAsk: (question: string, followUpOf: string | null) => void;
  onRetry: () => void;
  onDismissError: () => void;
  onClear: () => Promise<void>;
  onOpenDocument: (documentId: string) => void;
  onSelectExchange: (exchangeId: string) => void;
}

export function QuestionPanel({
  conversation,
  historyError,
  pending,
  failed,
  selection,
  isDocumentAvailable,
  onAsk,
  onRetry,
  onDismissError,
  onClear,
  onOpenDocument,
  onSelectExchange,
}: Props) {
  const [question, setQuestion] = useState('');
  const [followUpId, setFollowUpId] = useState<string | null>(null);
  const [confirmingClear, setConfirmingClear] = useState(false);
  const [highlightedId, setHighlightedId] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const threadEndRef = useRef<HTMLDivElement>(null);

  const byId = useMemo(() => new Map(conversation.map(e => [e.id, e])), [conversation]);
  // A follow-up target that disappeared (e.g. history cleared) is silently dropped.
  const followUpTarget = followUpId ? byId.get(followUpId) ?? null : null;

  // Keep the newest exchange, pending question or error in view.
  useEffect(() => {
    threadEndRef.current?.scrollIntoView({ block: 'end' });
  }, [conversation.length, pending, failed]);

  // Scroll to, focus and briefly highlight an exchange selected elsewhere.
  useEffect(() => {
    if (!selection) return;
    const el = document.getElementById(`exchange-${selection.id}`);
    if (!el) return;
    el.scrollIntoView({ block: 'center', behavior: 'smooth' });
    el.focus({ preventScroll: true });
    setHighlightedId(selection.id);
    const timer = window.setTimeout(() => setHighlightedId(null), 1600);
    return () => window.clearTimeout(timer);
  }, [selection]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = question.trim();
    if (!trimmed || pending) return;
    onAsk(trimmed, followUpTarget?.id ?? null);
    setQuestion('');
    setFollowUpId(null);
  };

  const startFollowUp = (exchange: ConversationExchange) => {
    setFollowUpId(exchange.id);
    inputRef.current?.focus();
  };

  const confirmClear = async () => {
    setConfirmingClear(false);
    setFollowUpId(null);
    await onClear();
    inputRef.current?.focus();
  };

  const isEmpty = conversation.length === 0 && !pending && !failed;

  return (
    <section aria-labelledby="conversation-heading" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          padding: '8px 20px',
          borderBottom: '1px solid #0f3460',
          minHeight: '42px',
        }}
      >
        <h2 id="conversation-heading" style={{ fontSize: '14px', fontWeight: 600 }}>
          Conversation{' '}
          <span style={{ ...metaText, fontWeight: 400 }}>
            ({conversation.length} {conversation.length === 1 ? 'exchange' : 'exchanges'})
          </span>
        </h2>
        {conversation.length > 0 &&
          (confirmingClear ? (
            <div role="group" aria-label="Confirm clearing the conversation" style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
              <span style={{ fontSize: '12px' }}>Delete all {conversation.length} exchanges?</span>
              <button type="button" onClick={confirmClear} style={{ ...smallButton, background: '#8b2635', borderColor: '#8b2635', color: '#fff' }}>
                Clear
              </button>
              <button type="button" onClick={() => setConfirmingClear(false)} style={smallButton} autoFocus>
                Cancel
              </button>
            </div>
          ) : (
            <button type="button" onClick={() => setConfirmingClear(true)} style={smallButton}>
              Clear conversation
            </button>
          ))}
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '12px 20px' }}>
        {historyError && (
          <div role="alert" style={errorBox}>
            Could not load the conversation history: {historyError}
          </div>
        )}

        {isEmpty && !historyError && (
          <div style={{ color: '#888', textAlign: 'center', paddingTop: '40px', fontSize: '14px', lineHeight: 1.6 }}>
            No questions yet.
            <br />
            <span style={{ fontSize: '12px' }}>
              Ask a question below — answers cite the indexed documents they are based on, and the whole conversation stays here.
            </span>
          </div>
        )}

        <ol
          role="log"
          aria-label="Questions and answers"
          aria-live="polite"
          aria-relevant="additions"
          style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '12px' }}
        >
          {conversation.map(exchange => (
            <li key={exchange.id}>
              <ExchangeItem
                exchange={exchange}
                parent={exchange.followUpOf ? byId.get(exchange.followUpOf) ?? null : null}
                highlighted={highlightedId === exchange.id}
                isDocumentAvailable={isDocumentAvailable}
                onOpenDocument={onOpenDocument}
                onFollowUp={startFollowUp}
                onJumpTo={onSelectExchange}
              />
            </li>
          ))}

          {pending && (
            <li aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '8px' }}>
              <div style={userBubble}>{pending.question}</div>
              <div style={{ ...metaText, alignSelf: 'flex-start', fontSize: '13px' }}>Assistant is searching your documents…</div>
            </li>
          )}

          {failed && (
            <li style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '8px' }}>
              <div style={userBubble}>{failed.question}</div>
              <div role="alert" style={{ ...errorBox, alignSelf: 'flex-start', maxWidth: '88%' }}>
                <div>The question could not be answered: {failed.message}</div>
                <div style={{ display: 'flex', gap: '6px', marginTop: '8px' }}>
                  <button type="button" onClick={onRetry} style={smallButton}>Retry</button>
                  <button type="button" onClick={onDismissError} style={smallButton}>Dismiss</button>
                </div>
              </div>
            </li>
          )}
        </ol>
        <div ref={threadEndRef} />
      </div>

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '6px',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        {followUpTarget && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12px', color: '#c0c0e0' }}>
            <span id="follow-up-context" style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              ↪ Following up on “{followUpTarget.question}”
            </span>
            <button
              type="button"
              onClick={() => {
                setFollowUpId(null);
                inputRef.current?.focus();
              }}
              style={smallButton}
              aria-label="Cancel follow-up"
            >
              ✕
            </button>
          </div>
        )}
        <div style={{ display: 'flex' }}>
          <label htmlFor="question-input" className="visually-hidden">
            Ask a question about your documents
          </label>
          <input
            id="question-input"
            ref={inputRef}
            type="text"
            value={question}
            onChange={e => setQuestion(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Escape' && followUpTarget) {
                e.preventDefault();
                setFollowUpId(null);
              }
            }}
            aria-describedby={followUpTarget ? 'follow-up-context' : undefined}
            placeholder={followUpTarget ? 'Ask a follow-up question… (Esc to cancel)' : 'Ask a question about your documents...'}
            style={{
              flex: 1,
              padding: '10px 14px',
              background: '#1a1a2e',
              color: '#e0e0e0',
              border: '1px solid #0f3460',
              borderRadius: '6px',
              fontSize: '14px',
            }}
          />
          <button
            type="submit"
            disabled={!question.trim() || pending !== null}
            style={{
              marginLeft: '10px',
              padding: '10px 20px',
              background: '#533483',
              color: '#fff',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '14px',
              fontWeight: 500,
            }}
          >
            {pending ? 'Asking…' : 'Ask'}
          </button>
        </div>
      </form>
    </section>
  );
}

const errorBox: React.CSSProperties = {
  padding: '10px 14px',
  borderRadius: '8px',
  background: 'rgba(217, 83, 79, 0.12)',
  border: '1px solid #d9534f',
  color: '#f2b8b5',
  fontSize: '13px',
};

